var DATA = {"mode": "holes"};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="holes"){
  show("Standard","1/4 in holes on 1 in centers");
  show("Fits","standard pegboard hooks");
}else if(m==="panel"){
  show("Panel",DATA.w+" x "+DATA.h+" ft");
  show("Area",(DATA.w*DATA.h)+" sq ft");
  show("Material",DATA.mat);
}else if(m==="hooks"){
  console.log("Hook types:");DATA.types.forEach(function(t){console.log("  "+t);});
}else if(m==="layout"){
  console.log("Planned layout:");DATA.rows.forEach(function(r,i){console.log("  Row "+(i+1)+": "+r);});
}else if(m==="mount"){
  show("Mounting","spacers hold the board off the wall");
  show("Why","hooks need depth behind the board");
  show("Into","studs for loaded boards");
}else if(m==="weight"){
  show("Load",DATA.kg+" kg across "+DATA.hooks+" hooks");
  show("Per hook",(Math.round(DATA.kg/DATA.hooks*10)/10)+" kg average");
  show("Rule","heavy tools low and near studs");
}else if(m==="bins"){
  show("Bins","hook-on bins for screws and small parts");
  show("Labels","every bin labeled");
}else if(m==="shelf"){
  show("Shelves","hook-on shelves for boxes and testers");
  show("Depth",DATA.d+" in");
}else if(m==="steel"){
  show("Steel board","magnetic, stronger, pricier");
  show("Hardboard","classic brown, cheaper, plenty strong");
}else if(m==="plan"){
  show("Planning","trace tools on paper, arrange, then hang");
  show("Rule","most-used at hand height");
}else if(m==="shadow"){
  show("Shadowing","trace each tool's outline on the board");
  show("Result","missing tools are instantly visible");
}else if(m==="mistake"){
  show("Mistake",DATA.bad);show("Instead",DATA.good);
}else if(m==="care"){
  show("Care","dust yearly, tighten hooks");
  show("Hooks","replace bent ones - they drop tools");
}else if(m==="workflow"){
